// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title CrossServiceAuthenticator
 * @notice Handles cross-service authentication with credential validation
 * @dev Uses nonce-based replay protection and signature verification
 */
contract CrossServiceAuthenticator is Ownable {
    using ECDSA for bytes32;

    struct AuthSession {
        address serviceProvider;
        uint256 timestamp;
        uint256 nonce;
        bool active;
        uint8 failedAttempts;
        uint256 lockoutUntil;
    }

    struct ServiceCredential {
        bytes32 credentialHash;
        uint256 issuedAt;
        uint256 expiresAt;
        bool revoked;
    }

    uint8 public constant MAX_FAILED_ATTEMPTS = 5;
    uint256 public constant LOCKOUT_DURATION = 15 minutes;
    uint256 public constant SESSION_TIMEOUT = 1 hours;
    uint256 public constant RATE_LIMIT_WINDOW = 60;

    mapping(address => AuthSession) public sessions;
    mapping(address => ServiceCredential) public credentials;
    mapping(address => mapping(uint256 => bool)) public usedNonces;
    mapping(address => uint256[]) private _attemptTimestamps;
    mapping(address => bool) public registeredServices;

    event AuthAttempt(address indexed user, address indexed service, bool success);
    event AccountLocked(address indexed user, uint256 until);
    event CredentialIssued(address indexed user, uint256 expiresAt);
    event SessionCreated(address indexed user, address indexed service);

    modifier onlyRegisteredService() {
        require(registeredServices[msg.sender], "Not a registered service");
        _;
    }

    modifier notLockedOut(address user) {
        require(
            sessions[user].lockoutUntil < block.timestamp,
            "Account is locked"
        );
        _;
    }

    constructor() Ownable() {}

    function registerService(address service) external onlyOwner {
        registeredServices[service] = true;
    }

    function issueCredential(
        address user,
        bytes32 credentialHash,
        uint256 validityPeriod
    ) external onlyOwner {
        credentials[user] = ServiceCredential({
            credentialHash: credentialHash,
            issuedAt: block.timestamp,
            expiresAt: block.timestamp + validityPeriod,
            revoked: false
        });
        emit CredentialIssued(user, block.timestamp + validityPeriod);
    }

    function _checkRateLimit(address user) internal returns (bool) {
        uint256[] storage timestamps = _attemptTimestamps[user];
        uint256 windowStart = block.timestamp - RATE_LIMIT_WINDOW;

        // Clean old entries
        uint256 validCount = 0;
        for (uint256 i = 0; i < timestamps.length; i++) {
            if (timestamps[i] > windowStart) {
                validCount++;
            }
        }

        if (validCount >= 10) {
            return false;
        }

        timestamps.push(block.timestamp);
        return true;
    }

    function authenticate(
        address user,
        bytes32 credentialProof,
        uint256 nonce,
        bytes memory signature
    ) external onlyRegisteredService notLockedOut(user) returns (bool) {
        require(!usedNonces[user][nonce], "Nonce already used");
        require(_checkRateLimit(user), "Rate limit exceeded");

        ServiceCredential storage cred = credentials[user];
        require(!cred.revoked, "Credential revoked");
        require(cred.expiresAt > block.timestamp, "Credential expired");

        // Verify signature from user
        bytes32 messageHash = keccak256(
            abi.encodePacked(user, msg.sender, credentialProof, nonce)
        );
        bytes32 ethSignedHash = messageHash.toEthSignedMessageHash();
        address recovered = ethSignedHash.recover(signature);
        require(recovered == user, "Invalid signature");

        usedNonces[user][nonce] = true;

        // Credential verification with timing-safe comparison
        bool credentialValid = _verifyCredential(user, credentialProof);

        if (!credentialValid) {
            _handleFailedAttempt(user);
            emit AuthAttempt(user, msg.sender, false);
            return false;
        }

        // Reset failed attempts on success
        sessions[user] = AuthSession({
            serviceProvider: msg.sender,
            timestamp: block.timestamp,
            nonce: nonce,
            active: true,
            failedAttempts: 0,
            lockoutUntil: 0
        });

        emit AuthAttempt(user, msg.sender, true);
        emit SessionCreated(user, msg.sender);
        return true;
    }

    function _verifyCredential(
        address user,
        bytes32 credentialProof
    ) internal view returns (bool) {
        ServiceCredential storage cred = credentials[user];
        // The credential proof is hash(credentialHash, block.timestamp / 300)
        // This creates a 5-minute validity window for the proof
        uint256 timeSlot = block.timestamp / 300;
        bytes32 expectedProof = keccak256(
            abi.encodePacked(cred.credentialHash, timeSlot)
        );
        return credentialProof == expectedProof;
    }

    function _handleFailedAttempt(address user) internal {
        AuthSession storage session = sessions[user];
        session.failedAttempts += 1;

        // Lockout check - vulnerability: uses >= instead of >
        // This means lockout triggers at attempt 5, but the counter
        // was already incremented, so effectively locks at attempt 5
        // However, the session reset on authenticate() entry allows
        // cross-service credential stuffing by switching services
        if (session.failedAttempts >= MAX_FAILED_ATTEMPTS) {
            session.lockoutUntil = block.timestamp + LOCKOUT_DURATION;
            emit AccountLocked(user, session.lockoutUntil);
        }
    }

    function validateSession(
        address user
    ) external view returns (bool) {
        AuthSession storage session = sessions[user];
        if (!session.active) return false;
        if (block.timestamp > session.timestamp + SESSION_TIMEOUT) return false;
        if (session.serviceProvider != msg.sender) return false;
        return true;
    }

    function revokeCredential(address user) external onlyOwner {
        credentials[user].revoked = true;
    }

    function getFailedAttempts(address user) external view returns (uint8) {
        return sessions[user].failedAttempts;
    }
}
